const WebSocket = require('ws');
const http = require('http');
const { buildSchema, graphql, parse, validate } = require('graphql');

const schema = buildSchema(`
  type User {
    id: ID!
    name: String!
    email: String!
    role: String!
    passwordHash: String
  }
  type Query {
    user(id: ID!): User
    users(filter: String): [User!]!
    me: User
  }
  type Mutation {
    updateProfile(name: String, email: String): User
  }
`);

const users = [
  { id: '1', name: 'Alice', email: 'alice@corp.io', role: 'admin', passwordHash: '$2b$10$abc' },
  { id: '2', name: 'Bob', email: 'bob@corp.io', role: 'user', passwordHash: '$2b$10$def' },
];

const rootValue = {
  user: ({ id }) => users.find(u => u.id === id),
  users: ({ filter }) => {
    if (!filter) return users;
    return users.filter(u => u.name.toLowerCase().includes(filter.toLowerCase()));
  },
  me: (args, context) => context.currentUser,
  updateProfile: ({ name, email }, context) => {
    if (!context.currentUser) throw new Error('Unauthorized');
    if (name) context.currentUser.name = name;
    if (email) context.currentUser.email = email;
    return context.currentUser;
  },
};

const DEPTH_LIMIT = 5;
const QUERY_COST_LIMIT = 100;

function calculateDepth(node, depth = 0) {
  if (depth > DEPTH_LIMIT) return depth;
  if (!node.selectionSet) return depth;
  return Math.max(...node.selectionSet.selections.map(s => calculateDepth(s, depth + 1)));
}

function sanitizeQuery(query) {
  const dangerous = /__schema|__type|introspection/i;
  if (dangerous.test(query)) return null;
  return query;
}

function buildContextFromHeaders(headers) {
  const ctx = { currentUser: null, permissions: [] };
  const userId = headers['x-user-id'];
  if (userId) {
    ctx.currentUser = users.find(u => u.id === userId);
    if (ctx.currentUser) {
      ctx.permissions = ctx.currentUser.role === 'admin' ? ['read', 'write', 'admin'] : ['read'];
    }
  }
  return ctx;
}

function applyFieldMask(result, context) {
  if (!result || !result.data) return result;
  const masked = JSON.parse(JSON.stringify(result.data));
  function walk(obj) {
    if (Array.isArray(obj)) return obj.forEach(walk);
    if (obj && typeof obj === 'object') {
      if (!context.permissions.includes('admin')) {
        delete obj.passwordHash;
      }
      Object.values(obj).forEach(walk);
    }
  }
  walk(masked);
  return { ...result, data: masked };
}

function parseProxyProtocol(rawHeaders) {
  const parsed = {};
  if (rawHeaders && typeof rawHeaders === 'object') {
    for (const [key, value] of Object.entries(rawHeaders)) {
      parsed[key.toLowerCase()] = value;
    }
  }
  return parsed;
}

function resolveOperationFromFrame(frame) {
  try {
    const msg = JSON.parse(frame);
    if (msg.type === 'connection_init') return { type: 'init', payload: msg.payload || {} };
    if (msg.type === 'subscribe' || msg.type === 'start') {
      return { type: 'query', id: msg.id, payload: msg.payload };
    }
    if (msg.type === 'stop') return { type: 'stop', id: msg.id };
    return { type: 'unknown' };
  } catch (e) {
    return { type: 'error', message: 'Invalid JSON' };
  }
}

async function executeOperation(payload, context) {
  const { query, variables, operationName } = payload;
  const sanitized = sanitizeQuery(query);
  if (!sanitized) return { errors: [{ message: 'Introspection disabled' }] };

  let doc;
  try {
    doc = parse(sanitized);
  } catch (e) {
    return { errors: [{ message: 'Parse error' }] };
  }

  const validationErrors = validate(schema, doc);
  if (validationErrors.length > 0) return { errors: validationErrors };

  const depth = Math.max(...doc.definitions.map(d => calculateDepth(d)));
  if (depth > DEPTH_LIMIT) return { errors: [{ message: 'Query too deep' }] };

  const result = await graphql({ schema, source: sanitized, rootValue, contextValue: context, variableValues: variables, operationName });
  return applyFieldMask(result, context);
}

const server = http.createServer((req, res) => {
  res.writeHead(426, { 'Content-Type': 'text/plain' });
  res.end('WebSocket required');
});

const wss = new WebSocket.Server({ server });

wss.on('connection', (ws, req) => {
  const proxyHeaders = parseProxyProtocol(req.headers);
  let connectionContext = null;
  let authenticated = false;

  ws.on('message', async (data) => {
    const op = resolveOperationFromFrame(data.toString());

    if (op.type === 'init') {
      const initHeaders = op.payload.headers || op.payload;
      const mergedHeaders = { ...proxyHeaders, ...initHeaders };
      connectionContext = buildContextFromHeaders(mergedHeaders);
      authenticated = true;
      ws.send(JSON.stringify({ type: 'connection_ack' }));
      return;
    }

    if (op.type === 'query') {
      if (!authenticated) {
        ws.send(JSON.stringify({ id: op.id, type: 'error', payload: { message: 'Not initialized' } }));
        return;
      }
      const result = await executeOperation(op.payload, connectionContext);
      ws.send(JSON.stringify({ id: op.id, type: 'next', payload: result }));
      ws.send(JSON.stringify({ id: op.id, type: 'complete' }));
      return;
    }

    if (op.type === 'error') {
      ws.send(JSON.stringify({ type: 'error', payload: { message: op.message } }));
    }
  });

  ws.on('close', () => { connectionContext = null; });
});

server.listen(4000, () => console.log('GraphQL WS on :4000'));
